describe('Async Image Upload with Progress Percentage', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/upload');
    cy.intercept('POST', '/api/upload', (req) => {
      req.reply((res) => {
        res.delay(2000);
        res.send({
          statusCode: 200,
          body: { success: true, fileId: '12345' }
        });
      });
    }).as('uploadRequest');

    cy.intercept('GET', '/api/upload/progress/*', (req) => {
      req.reply((res) => {
        res.send({
          statusCode: 200,
          body: { progress: 100, status: 'completed' }
        });
      });
    }).as('progressRequest');
  });

  it('should display progress percentage during image upload', () => {
    const fileName = 'test-image.jpg';

    cy.get('input[type="file"]').selectFile('cypress/fixtures/sample-image.jpg', { force: true });

    cy.get('button[data-testid="upload-btn"]').click();

    cy.get('[data-testid="progress-container"]').should('be.visible');

    cy.get('[data-testid="progress-percentage"]').should('contain', '0%');

    cy.get('[data-testid="progress-bar"]').should('exist');

    cy.wait('@uploadRequest');

    cy.get('[data-testid="progress-percentage"]', { timeout: 5000 }).should(($el) => {
      const percentage = parseInt($el.text());
      expect(percentage).to.be.greaterThan(0);
      expect(percentage).to.be.lessThanOrEqual(100);
    });

    cy.get('[data-testid="progress-percentage"]', { timeout: 10000 }).should('contain', '100%');

    cy.get('[data-testid="upload-success-message"]').should('be.visible').and('contain', 'Upload completed successfully');

    cy.get('[data-testid="progress-container"]').should('not.be.visible');
  });

  it('should handle upload failure and display error message', () => {
    cy.intercept('POST', '/api/upload', {
      statusCode: 500,
      body: { error: 'Server error during upload' }
    }).as('uploadFailure');

    cy.get('input[type="file"]').selectFile('cypress/fixtures/sample-image.jpg', { force: true });

    cy.get('button[data-testid="upload-btn"]').click();

    cy.get('[data-testid="progress-container"]').should('be.visible');

    cy.wait('@uploadFailure');

    cy.get('[data-testid="upload-error-message"]', { timeout: 5000 })
      .should('be.visible')
      .and('contain', 'Upload failed');

    cy.get('[data-testid="progress-container"]').should('not.be.visible');

    cy.get('button[data-testid="upload-btn"]').should('be.enabled');
  });

  it('should update progress percentage in real-time during upload', () => {
    let progressValues = [];

    cy.intercept('POST', '/api/upload', (req) => {
      req.reply((res) => {
        res.delay(3000);
        res.send({
          statusCode: 200,
          body: { success: true, fileId: '12345' }
        });
      });
    }).as('uploadRequest');

    cy.get('input[type="file"]').selectFile('cypress/fixtures/sample-image.jpg', { force: true });

    cy.get('button[data-testid="upload-btn"]').click();

    cy.get('[data-testid="progress-percentage"]').should('be.visible');

    cy.get('[data-testid="progress-percentage"]').then(($el) => {
      progressValues.push(parseInt($el.text()));
    });

    cy.wait(500);

    cy.get('[data-testid="progress-percentage"]').then(($el) => {
      progressValues.push(parseInt($el.text()));
    });

    cy.wait(500);

    cy.get('[data-testid="progress-percentage"]').then(($el) => {
      progressValues.push(parseInt($el.text()));
    });

    cy.wait('@uploadRequest');

    cy.get('[data-testid="progress-percentage"]', { timeout: 5000 }).should('contain', '100%');

    cy.wrap(progressValues).then((values) => {
      expect(values.length).to.be.greaterThan(0);
      values.forEach((val) => {
        expect(val).to.be.greaterThanOrEqual(0);
        expect(val).to.be.lessThanOrEqual(100);
      });
    });
  });

  it('should cancel upload and reset progress', () => {
    cy.get('input[type="file"]').selectFile('cypress/fixtures/sample-image.jpg', { force: true });

    cy.get('button[data-testid="upload-btn"]').click();

    cy.get('[data-testid="progress-container"]').should('be.visible');

    cy.get('[data-testid="progress-percentage"]').should('contain', '0%');

    cy.get('button[data-testid="cancel-btn"]').click();

    cy.get('[data-testid="progress-container"]').should('not.be.visible');

    cy.get('[data-testid="progress-percentage"]').should('not.exist');

    cy.get('input[type="file"]').should('have.value', '');
  });

  it('should handle multiple sequential uploads with independent progress tracking', () => {
    cy.get('input[type="file"]').selectFile('cypress/fixtures/sample-image.jpg', { force: true });

    cy.get('button[data-testid="upload-btn"]').click();

    cy.get('[data-testid="progress-percentage"]').should('be.visible');

    cy.wait('@uploadRequest');

    cy.get('[data-testid="progress-percentage"]', { timeout: 5000 }).should('contain', '100%');

    cy.get('[data-testid="upload-success-message"]').should('be.visible');

    cy.get('input[type="file"]').selectFile('cypress/fixtures/sample-image.jpg', { force: true });

    cy.get('button[data-testid="upload-btn"]').click();

    cy.get('[data-testid="progress-percentage"]').should('contain', '0%');

    cy.wait('@uploadRequest');

    cy.get('[data-testid="progress-percentage"]', { timeout: 5000 }).should('contain', '100%');
  });
});
